// The French catalogue: the language of origin. Each text is the one the interface showed before there was a catalogue, to the character.
// Keys are `area.slug-of-the-french-text` as the text read the day the key was made: a text that is reworded keeps its key, which is a name and not
// a copy of the text (renaming a key touches every file that reads it). The exception is a key that has come to say something else than its text
// (another verb, a name the interface no longer uses, another count): it misleads whoever translates or reads the code, and is renamed everywhere
// at once. {name} is a variable; a count is a pair `key.one` / `key.other` (see i18n.ts).
// A new text is written here first, then in i18n-en.ts (i18n.test.ts fails for a key one has and the other does not).
// Texts are typed with ordinary spaces, « like this » and before « : ; ! ? % »: the translator puts the non-breaking ones in (french-typography.ts).
import { littleForms } from './little-name'

// The words of the small window (little-name.ts): the one place that names it, read by the sentences below that speak of it.
