  'features.un-dossier-de-la-barre-laterale-se-remplit-des': 'Un dossier de la barre latérale se remplit des derniers éléments d’un flux ou d’un dépôt public : une requête sans compte toutes les 30 minutes pour chaque dossier créé, rien sans dossier.',
