  'features.un-site-de-visioconference-peut-ouvrir': 'Un site de visioconférence peut ouvrir, après un clic, une petite fenêtre qui reste au-dessus des autres, avec ses propres boutons (micro, caméra, raccrocher). Elle garde la session du site et se ferme avec sa page. À l’essai : le moteur ne la montre pas de lui-même, Lucium la reprend.',
  'features.une-petite-fenetre-d-appel-video-qui-reste': 'Une petite fenêtre d’appel vidéo qui reste au-dessus des autres, avec ses boutons.',
