  'features.une-tuile-apres-les-favoris-ouvre-en-un-clic': 'Une tuile après les favoris ouvre en un clic, en vue scindée, 2 à 4 sites choisis à l’avance, à leur place et dans leurs proportions. On l’enregistre depuis une vue scindée ouverte (bouton « Options de la vue scindée »). Coupée, les tuiles disparaissent, mais rien n’est effacé.',
  'features.un-site-securise-peut-apres-un-clic-demander-a': 'Un site sécurisé peut, après un clic, demander à utiliser un appareil que vous choisissez dans une liste qui le nomme ; jamais une clé de sécurité, un clavier ou une souris. Les appareils autorisés se retirent dans {settingsPath}.',
  'features.une-barre-au-pied-de-la-barre-laterale-pilote': 'Une barre au pied de la barre latérale pilote la lecture d’un onglet laissé de côté (pause, piste, volume). Désactivé, aucune page ne reçoit son script.',
  'features.une-barre-au-pied-de-la-barre-laterale': 'Une barre au pied de la barre latérale pilote la lecture d’un autre onglet.',
  'features.une-carte-montre-le-titre-l-adresse-et-une': 'Une carte montre le titre, l’adresse et une vignette de la page. Les vignettes sont prises en mémoire.',
  'features.une-commande-affichage-barre-de-commandes': 'Une commande (Affichage, barre de commandes, raccourci à choisir) masque d’un coup la barre latérale et la barre d’outils. La barre latérale revient au bord de la fenêtre et y montre l’adresse à la place du titre de l’onglet actif ; la barre d’outils reste masquée.',
  'features.une-commande-cache-d-un-coup-la-barre': 'Une commande cache d’un coup la barre latérale et la barre d’outils.',
