  'features.une-fenetre-ouverte-apres-la-premiere-montre': 'Une fenêtre ouverte après la première montre les onglets épinglés et ceux qu’elle ouvre elle-même, pas les onglets du jour des autres ; les extensions ne voient que les onglets de la première fenêtre.',
  'features.chaque-nouvelle-fenetre-a-ses-propres': 'Chaque nouvelle fenêtre a ses propres onglets du jour.',
  'features.une-feuille-liste-ce-qui-a-change-au-premier': 'Au premier lancement d’une nouvelle version, une feuille liste ce qui a changé, lu dans le journal des changements livré avec l’application ; rien n’est téléchargé.',
