  'features.une-video-que-vous-regardez-flotte-dans': 'Une vidéo que vous regardez flotte dans une petite fenêtre quand vous changez d’onglet, si elle joue avec le son (ou si c’est une visioconférence) depuis au moins 2 secondes et mesure au moins 320 × 180 pixels. Fermée deux fois sur un même site, la fenêtre ne s’y ouvre plus d’elle-même jusqu’à ce que vous quittiez Lucium.',
