  'guard-settings.ajoute-un-bruit-leger-stable-sur-un-site': 'Ajoute un bruit léger, stable sur un site pendant la session, à ce qu’une page lit d’un canvas, de WebGL et de l’audio ; réduit les chiffres annoncés par navigator ; cache à WebRTC les adresses du Mac. Peut casser des sites.',
  'guard-settings.un-bruit-leger-sur-ce-qu-une-page-lit-de': 'Un bruit léger sur ce qu’une page lit de votre appareil ; peut casser des sites.',
  'guard-settings.applique-les-regles-js-redirect': 'Applique les règles +js(), $redirect, $removeparam et $csp des listes avec des scripts de Lucium : une liste nomme un scriptlet, elle n’apporte jamais de code. Peut casser des sites. Ne concerne pas YouTube : ses règles du lecteur suivent le blocage des publicités, même cette option désactivée.',
