  'guard-settings.ecran-arrondi-a-une-taille-courante-carte': 'Bruit plus dense, aussi sur les grands canvas et les sons longs ; écran arrondi à une taille courante, carte graphique générique, aucune liste de polices installées, 4 cœurs et 4 Go au plus, workers partagés retirés. Plus de sites risquent de se comporter autrement.',
  'guard-settings.brouille-davantage-l-empreinte-de-l-appareil': 'Brouille davantage l’empreinte de l’appareil ; plus de sites risquent de mal fonctionner.',
  'guard-settings.la-liste-est-pleine': 'La liste est pleine.',
  'guard-settings.mode-strict-de-la-protection-contre-l-empreinte': 'Mode strict de la protection contre l’empreinte',
