  'guard-settings.protection-contre-l-empreinte-numerique': 'Protection contre l’empreinte numérique',
  'guard-settings.s-applique-a-la-page-que-vous-ouvrez-au': 'S’applique au chargement suivant, à la page, aux cadres qu’elle contient et aux scripts qu’elle lance en arrière-plan (workers). Les workers partagés ne sont pas couverts : ils restent disponibles et lisent les valeurs réelles du Mac, sauf en mode strict, qui les retire des pages protégées. Tant qu’une extension débogue une page, ses cadres et ses workers ne sont pas protégés. Les fenêtres privées et invité suivent ces réglages.',
  'guard-settings.s-applique-a-la-page-suivante-que-vous': 'S’applique à la page suivante que vous ouvrez.',
  'guard-settings.scriptlets-et-regles-etendues-du-bloqueur': 'Scriptlets et règles étendues du bloqueur',
