  'guard-settings.un-site-de-la-liste-couvre-aussi-ses-sous-domaines': 'Un site de la liste couvre aussi ses sous-domaines. À utiliser pour un site que la protection empêche de fonctionner (éditeur d’images, jeu, visioconférence). Les sites de la liste « Sites sans blocage » (Bloqueur) sont aussi laissés de côté par cette protection.',
  'guest-settings.desactive-l-entree-et-son-raccourci': 'Désactivé, l’entrée et son raccourci disparaissent. Les fenêtres invité déjà ouvertes restent jusqu’à leur fermeture.',
  'guest-settings.profil-invite': 'Profil invité',
  'guest-settings.proposer-nouvelle-fenetre-invite-dans-le-menu': 'Proposer « Nouvelle fenêtre invité » dans le menu Fichier',
  'guest-settings.une-fenetre-invite-garde-une-session-en': 'Une fenêtre invité garde une session en mémoire, effacée à sa fermeture : ni historique, ni cookies, ni extensions, ni rien de vos espaces, de vos favoris, de vos réglages ou de vos permissions. Elle suit seulement votre moteur de recherche, vos raccourcis, votre apparence (taille, clair ou sombre) et vos protections. Elle ne ressemble pas à une fenêtre privée : elle s’appelle « Invité ». Les fichiers téléchargés restent dans le dossier Téléchargements, et les Réglages ne s’y ouvrent pas.',
