  'key-ext-settings.pour-les-extensions-qui-regroupent-des': 'Pour les extensions qui regroupent des onglets (chrome.tabGroups). Un onglet de groupe est épinglé tant que le groupe existe : fermé, il s’endort comme tout onglet épinglé.',
  'key-ext-settings.site-sans-touches-de-type-vim': 'Site sans touches de type Vim',
  'key-ext-settings.sites-sans-touches-de-type-vim': 'Sites sans touches de type Vim',
  'key-ext-settings.tant-que-le-groupe-existe-ses-onglets-sont': 'Tant que le groupe existe, ses onglets sont épinglés dans un dossier de la barre latérale, puis remis où ils étaient ; le dossier n’est jamais gardé dans vos données. Le titre du groupe nomme le dossier ; un dossier supprimé ou un onglet sorti à la main n’est pas remis.',
  'key-ext-settings.tapez-le-mot-cle-un-espace-votre-texte': 'Tapez le mot-clé, un espace, votre texte, puis Entrée : l’extension reçoit le texte. Aucune suggestion n’est demandée à l’extension. Vos recherches dans un site passent avant (yt et celles que vous avez ajoutées ou modifiées) : un mot-clé identique ne répond plus.',
