  'lang.footnote': 'Les pages web et les noms que vous donnez (espaces, onglets, dossiers) ne sont jamais traduits. Dans le menu Aide, « Premiers pas » suit la langue de l’interface ; la documentation technique reste en français.',
  'lang.les-pages-web-et-les-noms-que-vous-donnez-ne': 'Les pages web et les noms que vous donnez ne sont jamais traduits.',
  'lang.hint': 'Menus, barre latérale, barre d’outils, barre de commandes, panneaux et réglages. Le français est la langue d’origine : un texte sans traduction reste en français.',
