  'launch-refusal.message': 'Le bac à sable de sécurité du moteur ne peut pas démarrer sur cet ordinateur.',
  'launch-refusal.cause-apparmor': 'Ubuntu 24.04 et les versions suivantes interdisent à un programme ordinaire de créer l’espace isolé dont ce bac à sable est fait, sauf si une règle AppArmor le permet, et une AppImage ne peut pas porter cette règle. Lucium ne démarre jamais sans bac à sable.',
  'launch-refusal.cause-autre': 'Ce système n’autorise pas un programme ordinaire à créer l’espace isolé dont ce bac à sable est fait (espaces de noms d’utilisateur désactivés ou restreints). Lucium ne démarre jamais sans bac à sable.',
  'launch-refusal.conseil-apparmor': 'Installez plutôt le paquet .deb de Lucium, qui apporte la règle nécessaire : la page Télécharger explique comment. Un administrateur peut aussi autoriser ces espaces sur l’ordinateur avec « sudo sysctl -w kernel.apparmor_restrict_unprivileged_userns=0 » (jusqu’au prochain redémarrage).',
  'launch-refusal.conseil-autre': 'Autorisez les espaces de noms d’utilisateur non privilégiés sur cet ordinateur (ou demandez-le à son administrateur), puis relancez Lucium. La page Télécharger donne les autres formes de Lucium pour Linux.',
