  'little-arc-settings.afficher-une-bulle-d-actions-apres-un': 'Afficher une bulle d’actions après un téléchargement',
  'little-arc-settings.garder-ouvert-exempte': `Le bouton « Garder ouvert » de l’en-tête (une épingle) exclut une ${little.s} de cet archivage.`,
  'little-arc-settings.le-delai-avant-l-archivage-d-une-fenetre': `Le délai avant l’archivage d’une ${little.s} oubliée se règle plus haut, dans « Fermer et archiver les ${little.p} oubliées ». ⌥⌘ est la seule combinaison que le moteur permet de reconnaître : ⌥ seul télécharge le lien et ⇧ ouvre un Coup d’œil. ⇧⌘-clic agit comme un clic sur un lien qui ouvre un nouvel onglet : une ${little.s} pour un lien vers un autre site quand la première option est activée, un onglet sinon. Ces options ne touchent pas les fenêtres privées ni les onglets privés.`,
  'little-arc-settings.ces-options-ne-touchent-pas-les-fenetres-et': 'Ces options ne touchent pas les fenêtres et les onglets privés.',
