  'lock-settings.une-fenetre-privee-laissee-seule-se-ferme-sur': 'Une fenêtre privée laissée seule (aucun clic ni touche, ou en arrière-plan) se couvre de l’écran de verrouillage et demande la phrase ou Touch ID. Ses onglets restent en mémoire, mais leurs pages sont fermées jusqu’au déverrouillage.',
  'lock-settings.c-est-un-verrou-de-l-interface-lucium': 'C’est un verrou de l’interface : Lucium masque vos onglets et met leurs pages en veille tant que la phrase n’a pas été saisie. Il ne chiffre ni vos cookies, ni vos profils, ni les fichiers du dossier des données : quiconque peut lire le disque de cet ordinateur peut les lire. La phrase n’est jamais enregistrée, seulement une empreinte, dans le fichier lock.json du dossier des données (hors des exports) ; si vous l’oubliez, supprimez ce fichier (Aide › Dépannage › Afficher les données de Lucium).',
  'lock-settings.un-verrou-de-l-interface-vos-fichiers-ne': 'Un verrou de l’interface : vos fichiers ne sont pas chiffrés, quiconque lit le disque peut les lire.',
