  'menu.nouveautes': 'Nouveautés',
  'menu-actions.a-votre-demande-seulement-le-chrome-web-store': 'À votre demande seulement : le téléchargement d’une mise à jour de Lucium (« Installer », ou « Rechercher les mises à jour… »), le Chrome Web Store, les modèles de traduction de Mozilla, le moteur de recherche d’un site, les pages surveillées, les dossiers en direct, la reprise d’un téléchargement, les images d’un export Markdown, le test du proxy, et le serveur DNS chiffré que vous choisissez.',
  'menu-actions.annuler': 'Annuler',
  'menu-actions.lucium-current-est-la-version-la-plus-recente': 'Lucium {current} est la version la plus récente.',
  'menu-actions.ce-fichier-n-est-pas-une-exportation-ou-une': 'Ce fichier n’est pas un export ou une sauvegarde de Lucium utilisable (version du format différente, ou fichier incomplet).',
  'menu-actions.choisissez-une-exportation-d-lucium-chiffree': 'Choisissez un export de Lucium (chiffré ou non) ou une sauvegarde du fichier d’état.',
  'menu-actions.demarrer-l-enregistrement': 'Démarrer l’enregistrement',
