  'menu-actions.enregistrer-une-trace-du-navigateur': 'Enregistrer une trace du navigateur ?',
  'menu-actions.export-des-signets-impossible': 'Export des signets impossible',
  'menu-actions.exportation-chiffree': 'Export chiffré',
  'menu-actions.exporter': 'Exporter…',
  'menu-actions.faites-ce-que-vous-voulez-examiner-puis': 'Faites ce que vous voulez examiner, puis choisissez à nouveau Aide › Dépannage › Arrêter et enregistrer la trace.',
  'menu-actions.la-liste-complete-avec-l-interrupteur-de-chaque': 'La liste complète, avec l’interrupteur de chaque connexion et sa valeur par défaut, est dans le README (section « Connections Lucium makes by itself »).',
  'menu-actions.la-trace-contient-les-adresses-des-pages-visitees': 'La trace contient les adresses des pages visitées pendant l’enregistrement, des titres d’onglets et des informations sur cet ordinateur. Le Bureau est proposé, et votre Mac peut le synchroniser : choisissez un autre dossier si besoin, et relisez la trace avant de la partager.',
  'menu-actions.la-trace-couvre-toutes-les-categories-d': 'La trace couvre toutes les catégories d’événements du moteur, sans filtre. Elle peut contenir les adresses des pages ouvertes, des titres d’onglets, des noms de fichiers et des informations sur cet ordinateur. Elle est enregistrée dans le fichier que vous choisirez en arrêtant l’enregistrement, et Lucium ne l’envoie nulle part : relisez-la avant de la partager. L’enregistrement peut ralentir le navigateur ; arrêtez-le dès que vous avez fait ce que vous voulez examiner.',
  'menu-actions.la-verification-des-mises-a-jour-a-echoue': 'La vérification des mises à jour a échoué',
  'menu-actions.la-verification-des-mises-a-jour-n-est-pas': 'La vérification des mises à jour n’est pas configurée',
  'menu-actions.les-mises-a-jour-se-font-a-la-main': 'Les mises à jour se font à la main',
  'menu-actions.vous-utilisez-lucium-current-telechargez-la-derniere': 'Vous utilisez Lucium {current}. Cette version ne cherche pas les mises à jour d’elle-même : pour avoir la dernière, téléchargez-la sur lucium.app.',
  'menu-actions.ouvrir-la-page-telecharger': 'Ouvrir la page Télécharger',
  'menu-actions.le-javascript-d-une-retouche-est-restaure': 'Le JavaScript d’une Retouche est restauré désactivé : relisez-le puis activez-le dans l’éditeur de la Retouche pour qu’il s’exécute.',
  'menu-actions.le-javascript-de-count-retouches-est-restaure': 'Le JavaScript de {count} Retouches est restauré désactivé : relisez-le puis activez-le dans l’éditeur de chaque Retouche pour qu’il s’exécute.',
  'menu-actions.les-donnees-ne-se-restaurent-pas-depuis-une': 'Les données ne se restaurent pas depuis une fenêtre privée : utilisez une fenêtre normale.',
  'menu-actions.les-favoris-les-onglets-epingles-et-les': 'Les favoris, les onglets épinglés et les dossiers de chaque espace sont écrits dans un fichier que tous les navigateurs savent importer.',
  'menu-actions.lucium-n-a-ni-compte-ni-synchronisation-ni': 'Lucium n’a ni compte, ni synchronisation, ni télémétrie : vos onglets, espaces, historique et réglages restent dans les données de l’application sur cet ordinateur.',
  'menu-actions.lucium-est-a-jour': 'Lucium est à jour',
  'menu-actions.ouvrir-le-readme': 'Ouvrir le README',
  'menu-actions.plus-tard': 'Plus tard',
  'menu-actions.pour-verifier-une-page-de-versions-indiquez-l': 'Pour vérifier une page de versions, indiquez l’adresse d’un flux « dernière version » (https), signé par la clé de cette version, dans le réglage updateFeedUrl des données de Lucium ; depuis les sources, la variable LUCIUM_UPDATE_FEED convient aussi.',
  'menu-actions.recherche-des-mises-a-jour': 'Recherche des mises à jour…',
  'menu-actions.restauration-impossible': 'Restauration impossible',
  'menu-actions.restaurer': 'Restaurer',
  'menu-actions.restaurer-spaces-et-tabs': 'Restaurer {spaces} et {tabs} ?',
  'menu-actions.restaurer-les-donnees': 'Restaurer les données',
  'menu-actions.saisissez-la-phrase-secrete-choisie-pour-ce': 'Saisissez la phrase secrète choisie pour ce fichier.',
  'menu-actions.sans-action-de-votre-part-partent-du-reseau': 'Sans action de votre part, ces connexions partent vers le réseau : les pages que vous ouvrez ; les listes de filtres du bloqueur, activé par défaut (téléchargées au premier lancement, puis vérifiées chaque heure) ; les icônes des sites, cherchées sur les sites eux-mêmes et affichées par la barre latérale ; les suggestions de recherche, vers votre moteur, pendant la frappe ; le fichier des versions de Lucium, sans cookie, à l’adresse des mises à jour intégrée à l’application (ou à celle que vous avez écrite), 20 s après le lancement puis une fois par jour, tant que « Rechercher les mises à jour automatiquement » est activé (c’est le cas par défaut) ; et, dans la variante DRM, le service de composants de Google à chaque lancement (Widevine).',
  'menu-actions.telecharger-manuellement': 'Télécharger manuellement',
  'menu-actions.trace-impossible': 'Trace impossible',
  'menu-actions.vos-espaces-onglets-dossiers-favoris-retouches': 'Vos espaces, onglets, dossiers, favoris, Retouches et réglages actuels sont remplacés. Les extensions chargées au démarrage, les hôtes de messagerie native d’un autre navigateur, l’adresse des mises à jour, le verrouillage, les dossiers de téléchargement, le proxy et le DNS restent ceux de cette installation : un fichier venu d’ailleurs ne les modifie pas. Il n’accorde pas non plus d’autorisation à un site (caméra, micro, position…) : seuls ses refus sont repris. L’historique, les cookies, les mots de passe et les scripts utilisateur ne sont pas dans un export : ils restent tels qu’ils sont ici. Les règles de vos listes de filtres, les images et les fonds des espaces n’y sont pas non plus : un fichier venu d’un autre Mac revient sans eux. Une copie de l’état actuel est gardée à côté du fichier d’état.',
  'menu-actions.surveiller-des-pages-les-commandes-par-adresse-et-la-recherche-des-mises-a-jour-restent': '« Surveiller des pages », « Commandes par adresse lucium:// » et « Rechercher les mises à jour automatiquement » restent allumés ou éteints comme ils le sont ici. Les pages à surveiller que liste le fichier ne sont reprises que si la surveillance est éteinte ici : elles attendent alors que vous l’allumiez.',
  'menu-actions.vous-utilisez-lucium-current-cette-version-n': 'Vous utilisez Lucium {current}. Cette version ne porte pas d’adresse de mises à jour. ',
  'menu-actions.vous-utilisez-current-cette-version-n-installe-pas': 'Vous utilisez {current}. Cette version n’installe pas les mises à jour elle-même : la page de téléchargement s’ouvre dans votre navigateur.',
  'menu.a-propos-d-lucium': 'À propos de Lucium',
  'menu.activer-le-mode-plein-ecran': 'Activer le mode plein écran',
  'menu.toujours-au-premier-plan': 'Toujours au premier plan',
  'menu.actualisation-forcee': 'Actualisation forcée',
  'menu.actualiser-la-page': 'Actualiser la page',
  'menu.actualiser-tous-les-onglets': 'Actualiser tous les onglets',
  'menu.affichage': 'Affichage',
