  'passwords-settings.le-coffre-l-import-et-l-export-sont-dans': 'Le coffre, l’import et l’export sont dans Fichier › Mots de passe… (ou « Mots de passe » dans la barre de commandes).',
  'passwords-settings.un-coffre-chiffre-sur-ce-mac-phrase-de': 'Un coffre chiffré sur cet ordinateur (phrase de {phraseMin} caractères au moins, AES-256 et scrypt), ni compte ni synchronisation. Un mot de passe n’est rempli que si vous le demandez (Fichier › Remplir l’identifiant et le mot de passe, la barre de commandes ou le panneau), sur une page de l’adresse exacte de l’identifiant, en https (ou http sur cet ordinateur), jamais dans un cadre et jamais dans une fenêtre ou un onglet privé. Lucium propose d’enregistrer un mot de passe saisi, sans jamais le faire seul. Le coffre se verrouille après {minutes} minutes sans usage, à la mise en veille, au verrouillage de l’écran et avec le verrou de Lucium ; il reste hors de l’export et des copies de la session. Les pages déjà ouvertes quand vous activez la fonction doivent être rechargées pour que la proposition d’enregistrement apparaisse.',
