  'persistence-notices.lucium-n-arrive-pas-a-ecrire-file-reason-vos': 'Lucium n’arrive pas à écrire « {file} » ({reason}). Vos changements de cette session restent en mémoire et Lucium réessaie régulièrement ; si le problème dure (disque plein, droits du dossier), ils seront perdus à la fermeture.',
  'persistence-notices.lucium-n-arrive-pas-a-ecrire-une-copie-de': 'Lucium n’arrive pas à écrire une copie de vos espaces et onglets dans son dossier de données ({reason}). ',
  'persistence-notices.lucium-ne-garde-que-les-trois-mises-de-cote': 'Lucium ne garde que les trois mises de côté les plus récentes de chaque fichier.',
