  'persistence-notices.vos-espaces-ne-sont-plus-proteges': 'Vos espaces et vos onglets ne sont plus protégés par une phrase. Pour remettre le verrou, choisissez une nouvelle phrase dans {settingsPath}.',
  'persistence-notices.des-copies-automatiques-de-vos-espaces-et-onglets': 'Des copies automatiques de vos espaces et onglets existent : la plus récente date du {when}. Pour la remettre : menu Fichier › Sessions…, section « Copies automatiques ».',
  'persistence-notices.des-donnees-neuves': 'des données neuves',
  'persistence-notices.donnees-d-une-version-plus-recente-d-lucium': 'Données d’une version plus récente de Lucium',
  'persistence-notices.impossible-de-lire-thing': 'Impossible de lire {thing}',
  'persistence-notices.l-historique-d-un-de-vos-profils': 'l’historique d’un de vos profils',
  'persistence-notices.le-fichier-file-est-illisible-reason-et': 'Le fichier « {file} » est illisible ({reason}) et Lucium n’a pas pu le mettre de côté ({moveError}). ',
  'persistence-notices.le-fichier-file-est-illisible-reason-il-n-a-pas': 'Le fichier « {file} » est illisible ({reason}). Il n’a pas été supprimé, mais mis de côté ici : « {backup} ». ',
  'persistence-notices.le-fichier-file-thing-a-ete-ecrit-par-une': 'Le fichier « {file} » ({thing}) a été écrit par une version plus récente de Lucium que celle-ci ({reason}). Il n’est ni abîmé ni supprimé, mais mis de côté tel quel ici : « {backup} ». ',
  'persistence-notices.le-fichier-mis-de-cote-peut-etre-repare-a-la-main': 'Le fichier mis de côté peut être réparé à la main. ',
  'persistence-notices.le-fichier-mis-de-cote-peut-etre-repare-aide': 'Le fichier mis de côté peut être réparé à la main ; Aide › Restaurer les données… accepte une sauvegarde au bon format. ',
  'persistence-notices.lucium-a-demarre-avec-fresh': 'Lucium a démarré avec {fresh}.',
  'persistence-notices.lucium-demarre-avec-fresh-mais-n-ecrit-rien': 'Lucium démarre avec {fresh}, mais n’écrit rien dans ce fichier tant qu’il est là, pour ne pas l’écraser : les changements de cette session ne seront pas enregistrés. Vérifiez les droits et l’espace libre du dossier des données de Lucium, puis relancez Lucium.',
  'persistence-notices.pour-retrouver-ces-donnees-relancez-la-version': 'Pour retrouver ces données, relancez la version plus récente de Lucium, puis choisissez Aide › Restaurer les données… et ce fichier. ',
  'persistence-notices.lucium-running-est-plus-ancien-que-la-version': 'Lucium {running} est plus ancien que la version qui a enregistré vos données',
  'persistence-notices.vos-donnees-ont-ete-enregistrees-par-lucium-writer': 'Vos espaces, onglets et réglages ont été enregistrés par Lucium {writer}, une version plus récente que celle-ci ({running}). Avant d’y toucher, Lucium en a gardé une copie ici : « {copy} ».',
  'persistence-notices.cette-version-peut-ne-pas-connaitre': 'Cette version peut ne pas connaître tout ce que ce fichier contient, et elle ne garde pas ce qu’elle ne connaît pas. Pour le retrouver, revenez à Lucium {writer} ou à une version plus récente, puis choisissez Aide › Restaurer les données… et cette copie. ',
  'persistence-notices.lucium-ne-garde-que-les-trois-copies-de-cette-sorte': 'Lucium ne garde que les trois copies les plus récentes de cette sorte.',
  'persistence-notices.vos-donnees-ont-ete-enregistrees-par-lucium-writer-sans-copie': 'Vos espaces, onglets et réglages ont été enregistrés par Lucium {writer}, une version plus récente que celle-ci ({running}). Lucium n’a pas pu en faire une copie ({reason}).',
  'persistence-notices.pour-ne-rien-perdre-cette-version-n-ecrit-rien': 'Pour ne rien perdre, cette version n’écrit rien dans « {file} » : ce que vous changez pendant cette session ne sera pas enregistré. Libérez de la place sur le disque ou vérifiez les droits du dossier de données, puis relancez Lucium, ou revenez à Lucium {writer}.',
  'persistence-notices.une-copie-de-vos-donnees-peut-etre-reprise': 'Une copie de vos données peut être reprise',
  'persistence-notices.avant-votre-retour-a-une-version-plus-ancienne': 'Vous avez utilisé une version plus ancienne de Lucium, qui n’a peut-être pas tout gardé de vos espaces, onglets et réglages. Avant qu’elle n’y touche, Lucium en avait gardé une copie ici : « {copy} ».',
  'persistence-notices.pour-reprendre-cette-copie': 'Pour la reprendre, choisissez Aide › Restaurer les données… et ce fichier. Ce que vous avez changé depuis sera remplacé ; Lucium en garde une copie avant de restaurer.',
  'persistence-notices.un-historique-vide': 'un historique vide',
  'persistence-notices.vos-donnees-et-vos-reglages-ne-sont-pas-touches': 'Vos données et vos réglages ne sont pas touchés, mais aucune copie ne sera gardée tant que le problème dure (disque plein, droits du dossier). Lucium réessaie à chaque copie prévue.',
