  'privacy-extra-settings.celui-du-reseau-aucun': 'Celui du réseau (aucun serveur choisi)',
  'privacy-extra-settings.chaque-interrupteur-est-reel-desactive-la': 'Désactivée, une fonction ne fait plus rien du tout. « Cookies par site » est dans le menu Affichage et dans la barre de commandes.',
  'privacy-extra-settings.desactive-le-moteur-decide-seul-mode': 'Désactivé, le moteur décide seul (mode automatique) : c’est le réglage par défaut.',
