  'privacy-extra-settings.fichier-nouvel-onglet-prive-une-session-en': 'Fichier › Nouvel onglet privé : une session en mémoire, ni enregistrée ni dans l’historique, perdue à la fermeture du dernier onglet privé.',
  'privacy-extra-settings.historique-cookies-et-onglets-prives': 'Historique et données',
  'privacy-extra-settings.https-dns-exemple-org-dns-query': 'https://dns.example.org/dns-query',
  'privacy-extra-settings.https-hote-dns-query-seul-https-est': 'https://hôte/dns-query — seul https est accepté, sans identifiant.',
  'privacy-extra-settings.la-liste-des-cookies-de-chaque-site-noms': 'La liste des cookies de chaque site (noms et tailles, jamais le contenu), les sites à garder toujours et le nettoyage qui les épargne.',
  'privacy-extra-settings.le-proxy-s-applique-aux-pages-aux-fenetres': 'Le proxy s’applique aux pages, aux fenêtres privées et aux requêtes de Lucium (suggestions, listes de filtres, mises à jour). Un profil peut avoir le sien (Profils) ; ses onglets privés et ses conteneurs gardent le proxy général. Les domaines locaux restent directs.',
  'privacy-extra-settings.le-proxy-vaut-aussi-pour-les-fenetres': 'Le proxy vaut aussi pour les fenêtres privées et les requêtes de Lucium.',
  'privacy-extra-settings.le-serveur-choisi-voit-les-noms-de-domaine': 'Le serveur choisi voit les noms de domaine que vous visitez, à la place de celui de votre réseau. Rien n’est contacté sans votre choix.',
  'privacy-extra-settings.les-pages-visitees-ne-sont-plus-ajoutees-a': 'Désactivé, les pages visitées ne sont plus ajoutées à l’historique ; ce qui s’y trouve déjà reste (Archive › Afficher l’historique permet de l’oublier). Un profil peut décider autrement (Profils).',
  'privacy-extra-settings.mode-du-dns-chiffre': 'Mode du DNS chiffré',
  'privacy-extra-settings.garder-l-historique-des-pages-visitees': 'Garder l’historique des pages visitées',
  'privacy-extra-settings.quand-vous-copiez-une-adresse-copier-l-adresse': 'Quand vous copiez une adresse (« Copier l’adresse », « Copier le lien »), {params}… en sont retirés. La liste est fixe ; aucun autre paramètre n’est touché.',
  'privacy-extra-settings.une-adresse-copiee-perd-ses-parametres-de': 'Une adresse copiée perd ses paramètres de suivi connus.',
  'privacy-extra-settings.regler-le-dns-chiffre-moi-meme': 'Régler le DNS chiffré moi-même',
