  'privacy-ipc.les-cookies-par-site-ne-sont-pas-disponibles-ici': 'Les cookies par site ne sont pas disponibles ici.',
  'privacy-ipc.site-non-valide-aucun-cookie-n-a-ete-retire': 'Site non valide : aucun cookie n’a été retiré.',
  'privacy-settings.ajoute-l-en-tete-sec-gpc-1-a-chaque': 'Ajoute l’en-tête « Sec-GPC: 1 » à chaque requête : vous refusez que le site vende ou partage vos données.',
  'privacy-settings.confidentialite-renforcee': 'Pistage et HTTPS',
  'privacy-settings.envoyer-le-signal-global-privacy-control': 'Demander aux sites de ne pas me suivre (signal GPC)',
  'privacy-settings.retirer-les-parametres-de-suivi-des-adresses': 'Retirer les paramètres de suivi des adresses',
  'privacy-settings.supprime-utm-fbclid-gclid-mc-eid-igshid': 'Supprime utm_*, fbclid, gclid, mc_eid, igshid, msclkid… des liens que vous ouvrez. Les autres paramètres ne sont pas touchés.',
  'privacy-settings.toujours-essayer-https-d-abord': 'Toujours essayer HTTPS d’abord',
  'privacy-settings.cookies-tiers': 'Cookies tiers',
  'privacy-settings.navigation-sure': 'Navigation sûre',
  'privacy-settings.prevenir-avant-d-ouvrir-un-site-dangereux': 'Prévenir avant d’ouvrir un site dangereux',
  'privacy-settings.compare-chaque-page-a-une-liste-livree': 'Avant d’ouvrir une page, Lucium compare son adresse à une liste de sites d’hameçonnage et de sites qui diffusent des logiciels malveillants.',
  'privacy-settings.la-liste-est-livree-avec-lucium': 'La liste est livrée avec l’application et renouvelée à chaque version : elle peut être en retard sur les sites récents. La comparaison se fait sur cet ordinateur ; aucune adresse n’est envoyée et rien n’est téléchargé. Seule la page principale est vérifiée (pas les cadres intégrés), jamais une page interne de Lucium. Seule l’adresse exacte du site est comparée : un sous-domaine qui n’est pas sur la liste passe. « Continuer quand même » ouvre le site dans toutes les fenêtres, privées comprises, jusqu’à la fermeture de Lucium ; « Ne plus prévenir pour ce site » (ou la liste des sites) l’exempte durablement.',
  'privacy-settings.sites-ou-la-navigation-sure-ne-previent-pas': 'Sites où la navigation sûre ne prévient pas',
  'privacy-settings.site-ou-ne-pas-prevenir': 'Site où ne pas prévenir',
  'privacy-settings.liste-indisponible': 'Liste indisponible : la liste de sites dangereux est absente ou illisible, aucun site n’est vérifié. Réinstallez Lucium pour la rétablir.',
  'features.compare-chaque-page-a-une-liste-de-sites': 'Compare chaque page à une liste de sites dangereux livrée avec l’application, sur cet ordinateur : rien n’est envoyé. Exceptions : {settingsPath}.',
  'discover.sure-resume': 'Prévient avant d’ouvrir un site d’hameçonnage ou de logiciels malveillants, d’après une liste livrée avec Lucium : rien n’est envoyé ni téléchargé.',
  'privacy-settings.bloquer-les-cookies-tiers': 'Bloquer les cookies tiers',
  'privacy-settings.un-site-integre-dans-une-autre-page-ne': 'Un contenu venu d’un autre site que celui de l’onglet (une image, un cadre, un script) ne reçoit aucun cookie et ne peut pas en déposer.',
  'privacy-settings.sont-concernes-les-cookies-envoyes-et-recus': 'Sont concernés les cookies envoyés et reçus par les requêtes de la page ; ceux qu’un script lit ou écrit lui-même (document.cookie) ne sont pas touchés. Certaines connexions (« Se connecter avec… ») et certains lecteurs intégrés en ont besoin : ajoutez alors le site à la liste ci-dessous. Vaut aussi en fenêtre privée et invité.',
  'privacy-settings.sites-ou-les-cookies-tiers-sont-acceptes': 'Sites où les cookies tiers sont acceptés',
  'privacy-settings.un-site-de-la-liste-couvre-aussi-ses-sous': 'Un site de la liste couvre aussi ses sous-domaines.',
  'privacy-settings.site-ou-accepter-les-cookies-tiers': 'Site où accepter les cookies tiers',
  'features.ouvre-l-adresse-finale-d-un-lien-de-suivi-ou-d-une': 'Ouvre l’adresse finale d’un lien qui passe par un redirecteur de suivi (l.facebook.com, google.com/url…) ou par une page AMP, sans rien demander à personne ; des sites peuvent être exceptés dans {settingsPath}.',
  'privacy-settings.contourner-les-redirections-de-suivi-et-les-pages-amp': 'Contourner les redirections de suivi et les pages AMP',
  'privacy-settings.un-lien-qui-passe-par-un-redirecteur-ou-une-page-amp-de-google': 'Un lien qui passe par un redirecteur de suivi ou une page AMP ouvre directement l’adresse du site.',
  'privacy-settings.seules-sont-depliees-les-adresses-qui-contiennent': 'Seules sont dépliées les adresses qui contiennent leur destination (liens de Facebook, Instagram, YouTube, Reddit, LinkedIn…, pages AMP), par calcul local : aucune requête n’est envoyée. Un raccourci dont la destination reste chez le service (t.co, bit.ly, lien d’un e-mail) n’est pas déplié. Le site qui pose problème se met dans la liste des exceptions. S’applique aussi en fenêtre privée et invité.',
  'privacy-settings.sites-dont-les-liens-restent-tels-quels': 'Sites dont les liens restent tels quels (redirections et AMP)',
  'privacy-settings.site-dont-les-liens-restent-tels-quels': 'Site dont les liens restent tels quels',
  'shields.liens-de-suivi-et-amp': 'Liens de suivi et pages AMP',
  'shields.adresses-finales-ouvertes-pour-ce-site': 'Ouvre l’adresse finale des liens de ce site',
  'shields.liens-laisses-tels-quels-pour-ce-site': 'Liens laissés tels quels pour ce site',
  'privacy-settings.quatre-protections-que-d-autres-navigateurs': 'Quatre protections que d’autres navigateurs proposent ; un nouveau profil les a toutes, un profil existant garde ses choix. Elles s’appliquent aussi aux fenêtres privées et invité, et prennent effet dès la navigation ou la copie suivante.',
  'privacy-settings.allumees-pour-un-nouveau-profil-elles-valent': 'Allumées pour un nouveau profil ; elles valent aussi en fenêtre privée et invité.',
  'privacy-settings.une-adresse-en-http-est-ouverte-en-https': 'Une adresse en http:// est ouverte en https:// ; si le site ne répond pas en HTTPS (refus ou silence de 5 secondes), la page s’ouvre en HTTP et un avis le signale. Un certificat non valide n’ouvre jamais la page en HTTP d’office : sa page d’erreur propose « Ouvrir en HTTP (non sécurisé) ». Les adresses locales et privées ne sont pas concernées.',
  'privacy-settings.ouvre-les-sites-en-connexion-chiffree-quand': 'Ouvre les sites en connexion chiffrée quand ils le permettent ; sinon, un avis le dit.',
  'privacy.host-ne-repond-pas-en-https-la-page-s-ouvre-en': '{host} ne répond pas en HTTPS : la page s’ouvre en HTTP, sans chiffrement.',
  'private-window.navigation-privee': 'Navigation privée',
