  'problem-report.ce-que-contient-le-rapport': 'Dans le rapport : la version et la variante de Lucium, le moteur, le système, les extensions (nom et version), les fonctions activées et le journal des erreurs, dont les chemins sont réduits au nom du fichier et les adresses au nom du site. Aucune page, aucun titre d’onglet, aucun mot de passe.',
