  'settings.clair-sombre-ou-celle-du-systeme-pour-les': 'Clair, sombre ou celle du Mac, pour Lucium lui-même : les Réglages, la barre latérale, les panneaux et toutes ses fenêtres. Les sites la suivent tant que « Apparence demandée aux sites » reste sur Automatique. Un espace dont le thème est réglé sur Clair ou Sombre garde le sien dans la barre latérale. Même choix que le menu Affichage › Apparence › Apparence de Lucium dans la barre de menus.',
  'settings.clair-sombre-ou-comme-le-mac-pour-les': 'Clair, sombre ou comme le Mac, pour les fenêtres et les panneaux de Lucium.',
  'settings.apparence-demandee-aux-sites': 'Apparence demandée aux sites',
  'settings.apparence-demandee-aux-sites-hint': 'Indique aux pages web si elles doivent s’afficher en clair ou en sombre : c’est ce qu’elles lisent comme préférence de thème du Mac. Automatique : les sites suivent Lucium. Cela ne change jamais Lucium lui-même ; pour recolorer une page qui n’a pas de thème sombre, voir « Contraste de la page ». Même choix que le menu Affichage › Apparence › Apparence demandée aux sites dans la barre de menus.',
  'settings.le-theme-clair-ou-sombre-que-les-sites': 'Le thème, clair ou sombre, que les sites reçoivent ; Automatique suit Lucium.',
