  'settings.desactive-l-onglet-s-ouvre-au-premier-plan': 'Désactivé, l’onglet s’ouvre au premier plan.',
  'settings.desactive-seuls-l-onglet-affiche-et-les': 'Désactivé, seuls se chargent au lancement l’onglet affiché de chaque fenêtre, les onglets marqués « Ne jamais mettre cet onglet en veille », ceux à rechargement automatique et un onglet par site gardé éveillé ; les autres restent en veille jusqu’à ce que vous les ouvriez. Activé, chaque onglet occupe de la mémoire dès le lancement.',
  'settings.chaque-onglet-se-charge-des-le-lancement-et': 'Chaque onglet se charge dès le lancement et occupe de la mémoire ; sinon, il attend d’être ouvert.',
  'settings.desactive-seuls-les-favoris-les-onglets': 'Désactivé, seuls les favoris, les onglets épinglés et les dossiers sont écrits.',
