  'settings.effacer': 'Effacer…',
  'settings.envoie-ce-que-vous-tapez-au-moteur-choisi': 'Envoie ce que vous tapez, dès deux caractères, au moteur choisi, sauf ce qui est une adresse (nom de domaine, adresse IP, localhost ou lien complet). Rien ne part dans une fenêtre privée ni au-dessus d’un onglet privé. Sans effet avec Qwant, Ecosia ou un moteur personnalisé : rien ne leur est demandé.',
