  'settings.geler': 'Garder en mémoire',
  'settings.glissez-un-onglet-de-la-barre-laterale-vers': 'Glissez un onglet de la barre latérale vers le bord gauche, droit, haut ou bas de la page pour créer une vue scindée. Sur une vue scindée, l’aperçu montre la case où il se posera : un bord l’ajoute à la rangée ou à la colonne, un coin passe la vue en grille (quatre volets au plus). Lâché au centre, rien ne change.',
  'settings.glissez-un-onglet-vers-un-bord-de-la-page': 'Glissez un onglet vers un bord de la page pour l’afficher à côté.',
