  'settings.jamais-pour-la-derniere-fenetre-la-fermer': 'Jamais pour la dernière fenêtre : la fermer revient à quitter.',
  'settings.les-icones-qui-ne-tiennent-pas-sur-la-ligne': 'Les icônes qui ne tiennent pas sur la ligne de la barre vont dans le menu « Autres extensions » (bouton »). Un clic droit sur une icône permet de l’épingler à la barre ou de la retirer (elle reste alors dans ce menu).',
  'settings.les-icones-qui-ne-tiennent-pas-dans-la-barre': 'Les icônes qui ne tiennent pas dans la barre vont dans le menu « Autres extensions ».',
  'settings.la-commande-nouvelle-mini-fenetre-n-a-pas-de-raccourci': `La commande « Nouvelle ${little.s} » n’a pas de raccourci : donnez-lui-en un dans la liste des raccourcis, plus bas dans cette catégorie.`,
  'settings.la-page-est-fermee-pour-liberer-la-memoire': 'La page est fermée pour libérer la mémoire ; elle se recharge quand on y revient.',
  'settings.la-page-reste-en-memoire-mais-ne-consomme': 'La page reste en mémoire mais ne consomme plus de processeur ; elle reprend aussitôt, dans son état. Une connexion en direct (messagerie…) peut se couper.',
  'settings.le-blocage-s-appuie-sur-les-listes-de': 'Le blocage s’appuie sur des listes de filtres (EasyList, uBlock…), téléchargées une fois l’option activée et réglables dans {settingsPath} ; en attendant, une courte liste intégrée est utilisée. Il ne bloque jamais la page elle-même, seulement ce qu’elle charge.',
  'settings.les-listes-de-filtres-se-telechargent-quand': 'Les listes de filtres se téléchargent quand le blocage est activé ; seul ce que la page charge est bloqué.',
  'settings.le-bouton-precedent-ferme-l-onglet-ouvert': 'Le bouton Précédent ferme l’onglet ouvert depuis un lien',
