  'settings.les-pages-recoivent-la-palette-de-l-espace': 'Les pages peuvent lire les couleurs du thème de l’espace (variables CSS --arc-palette-*, --arc-background-*).',
  'settings.les-panneaux-et-les-menus-flottants-deviennent': 'Les panneaux et les menus flottants deviennent opaques.',
  'settings.les-textes-gris-passent-en-gris-fonce-et-les': 'Les textes gris prennent presque la couleur du texte principal et les contours se renforcent.',
  'settings.les-versions-de-test-arrivent-avant-la-version': 'Les versions de test arrivent avant la version stable ; elles peuvent contenir des défauts.',
  'settings.liberer-la-memoire': 'Libérer la mémoire',
  'settings.la-mini-fenetre-est-une-fenetre-lucium-plus': `La ${little.s} est une fenêtre Lucium plus petite et plus simple, pour une recherche rapide ou un lien à lire sans quitter ce que vous faites.`,
  'settings.little-shortcut-on': `{shortcut} ouvre une ${little.s}, même quand une autre application est au premier plan.`,
  'settings.mettre-en-veille-les-onglets-inactifs': 'Mettre en veille les onglets inactifs',
  'settings.mode-de-veille': 'Mode de veille',
  'settings.modere': 'Modéré',
  'settings.equilibre': 'Équilibré',
  'settings.maximal': 'Maximal',
  'settings.personnalise': 'Personnalisé',
  'settings.quand-la-memoire-vient-a-manquer': 'Quand la mémoire du Mac vient à manquer, le délai passe à 5 minutes au plus et 4 onglets au plus restent éveillés en arrière-plan ; quand elle manque gravement, tout onglet que rien ne protège est mis en veille sans attendre son délai. Le mode économie de batterie ramène lui aussi le délai à 5 minutes au plus.',
  'settings.delai-de-mise-en-veille': 'Délai de mise en veille',
  'settings.apres-10-minutes': 'Après 10 minutes',
  'settings.apres-2-heures': 'Après 2 heures',
  'settings.onglets-eveilles-en-arriere-plan-au-plus': 'Onglets éveillés en arrière-plan, au plus',
  'settings.au-dela-l-onglet-quitte-depuis-le-plus': 'Toutes fenêtres confondues. Au-delà, l’onglet quitté depuis le plus longtemps est mis en veille avant son délai. Ne comptent pas les onglets que la veille épargne déjà : téléchargement, caméra, micro ou écran, texte non envoyé, image dans l’image, rechargement automatique, onglets marqués « Ne jamais mettre cet onglet en veille », onglets que la liste des sites garde éveillés, et, si vous les épargnez, les onglets qui jouent du son et les onglets épinglés.',
  'settings.au-dela-l-onglet-quitte-est-mis-en-veille-avant': 'Au-delà, l’onglet quitté depuis le plus longtemps est mis en veille avant son délai.',
  'settings.sans-limite': 'Sans limite',
  'settings.geler-d-abord-les-onglets-caches': 'Geler d’abord les onglets cachés',
  'settings.un-bouton-a-cote-de-infos-et-reglages-du-site': 'Un bouton à côté de « Infos et réglages du site » montre le mode de contraste du site affiché : chaque clic passe au mode suivant (Original, Sombre, Clair, puis Original), un clic droit propose tous les modes. Absent d’une page qui n’est pas web, d’un PDF et d’un onglet privé.',
  'settings.un-clic-sur-ce-bouton-passe-la-page-en-mode': 'Un clic sur ce bouton passe la page en mode sombre, clair ou original.',
  'settings.un-onglet-cache-depuis-ce-delai-ne': 'Un onglet caché depuis ce délai est gelé : sa page reste en mémoire mais ne consomme plus de processeur. En mode « Libérer la mémoire », elle est libérée au délai de mise en veille. Le gel épargne ce que la veille épargne, plus tout onglet qui joue du son et tous les onglets des sites gardés éveillés. Une messagerie gelée ne prévient plus.',
  'settings.un-onglet-cache-depuis-ce-delai-cesse-d': 'Un onglet caché depuis ce délai cesse d’utiliser le processeur, mais garde sa page en mémoire.',
  'settings.apres-2-minutes': 'Après 2 minutes',
  'settings.modifie': 'Modifié',
  'settings.ne-pas-mettre-en-veille-les-onglets-epingles': 'Ne pas mettre en veille les onglets épinglés',
  'settings.ne-pas-mettre-en-veille-les-onglets-epingles-aide': 'Activé, aucun onglet épinglé n’est mis en veille automatiquement, quel que soit son site. Désactivé, les épinglés suivent le délai et le plafond comme les autres.',
  'settings.les-onglets-epingles-ne-sont-jamais-mis-en': 'Les onglets épinglés ne sont jamais mis en veille d’eux-mêmes.',
  'settings.ne-pas-mettre-en-veille-les-onglets-qui': 'Ne pas mettre en veille les onglets qui jouent du son',
  'settings.ne-sont-jamais-mis-en-veille-l-onglet': 'Jamais mis en veille automatiquement : les onglets affichés (volets d’une vue scindée compris), un onglet qui télécharge un fichier, utilise la caméra, le micro ou l’écran, se recharge tout seul, montre une vidéo en image dans l’image ou garde du texte tapé non envoyé. Pour garder un onglet précis : son menu (clic droit) › Ne jamais mettre cet onglet en veille ; le même menu le met en veille ou le gèle tout de suite.',
  'settings.un-onglet-affiche-ou-occupe-telechargement': 'Un onglet affiché ou occupé (téléchargement, caméra, texte non envoyé…) n’est jamais mis en veille.',
  'settings.nettoie-le-nom-des-fichiers-telecharges': 'Nettoie le nom des fichiers téléchargés (« Rapport_final%20v2.PDF » devient « Rapport final v2.pdf »).',
