  'settings.par-defaut-lucium-les-ouvre-au-premier': `Désactivé, ces liens s’ouvrent au premier plan. Vers un autre site, ils s’ouvrent dans une ${little.s} tant que « Ouvrir en ${little.s} les liens qui ouvrent un nouvel onglet » est activé.`,
  'settings.un-lien-prevu-pour-un-nouvel-onglet-s-ouvre': 'Un lien prévu pour un nouvel onglet s’ouvre derrière la page affichée.',
  'settings.le-coup-d-oeil-affiche-un-lien-par-dessus-la-page': 'Le Coup d’œil affiche un lien par-dessus la page, sans ouvrir d’onglet ; Échap le referme.',
  'settings.mise-en-veille': 'Mise en veille',
  'settings.permet-a-une-extension-comme-claude-de': 'Permet à une extension comme Claude de joindre l’application qu’elle a installée pour un autre navigateur (Claude Code, application Claude). Lucium lance alors ces programmes : si cet autre navigateur et Lucium sont ouverts avec la même extension, la liaison peut aller à l’un ou à l’autre. Prend effet au prochain démarrage de l’extension.',
