  'site-privacy-settings.desactive-par-defaut-quand-le-dernier': 'Désactivé par défaut. Quand le dernier onglet d’un site de la liste se ferme ou est archivé, même automatiquement (pas quand il change de site), ses données sont effacées pour les types cochés dans « Effacer les données du site… » (⇧⌘X) : tous par défaut, cache et historique du site compris, sans toucher aux extensions. Chaque entrée couvre l’hôte indiqué, avec ses sous-domaines si cette option est cochée dans ce panneau.',
