  'privacy-settings.pings-more': 'Sont concernés l’attribut ping des liens et les envois de navigator.sendBeacon() vers un autre site que celui de la page. Ils sont annulés et comptés avec les éléments bloqués. Les sites de la liste des exceptions du bloqueur sont laissés tels quels. Vaut aussi en fenêtre privée et invité.',
